// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccountKinds 列出帳號種類
	// (GET /account-kinds)
	ListAccountKinds(ctx context.Context, request ListAccountKindsRequestObject) (ListAccountKindsResponseObject, error)
	// ListAccounts 列出帳號
	// (GET /accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount 建立帳號
	// (POST /accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// DeleteAccount 刪除帳號
	// (DELETE /accounts/{api_id})
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// GetAccount 取得帳號
	// (GET /accounts/{api_id})
	GetAccount(ctx context.Context, request GetAccountRequestObject) (GetAccountResponseObject, error)
	// UpdateAccount 更新帳號
	// (PUT /accounts/{api_id})
	UpdateAccount(ctx context.Context, request UpdateAccountRequestObject) (UpdateAccountResponseObject, error)
	// Login 以 token 換 cookie
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout 清掉 cookie
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe 目前的使用者
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// StreamEvents 狀態的即時更新（SSE）
	// (GET /events)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// ListInstances 列出 instance 與 controller
	// (GET /instances)
	ListInstances(ctx context.Context, request ListInstancesRequestObject) (ListInstancesResponseObject, error)
	// GetInstance 取得 instance
	// (GET /instances/{name})
	GetInstance(ctx context.Context, request GetInstanceRequestObject) (GetInstanceResponseObject, error)
	// ListSessionRecords 列出 session 的歷史紀錄
	// (GET /session-records)
	ListSessionRecords(ctx context.Context, request ListSessionRecordsRequestObject) (ListSessionRecordsResponseObject, error)
	// GetSessionRecord 取得一筆歷史紀錄
	// (GET /session-records/{record_id})
	GetSessionRecord(ctx context.Context, request GetSessionRecordRequestObject) (GetSessionRecordResponseObject, error)
	// ListSessions 列出 session
	// (GET /sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// CreateSession 部署 session
	// (POST /sessions)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)
	// DeleteSession 刪除 terminal 的 session
	// (DELETE /sessions/{session_id})
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
	// GetSession 取得 session
	// (GET /sessions/{session_id})
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// EndSession 結束 session
	// (POST /sessions/{session_id}/end)
	EndSession(ctx context.Context, request EndSessionRequestObject) (EndSessionResponseObject, error)
	// ListStrategies 列出策略
	// (GET /strategies)
	ListStrategies(ctx context.Context, request ListStrategiesRequestObject) (ListStrategiesResponseObject, error)
	// ListStrategyVersions 列出策略的版本
	// (GET /strategies/{strategy_id}/versions)
	ListStrategyVersions(ctx context.Context, request ListStrategyVersionsRequestObject) (ListStrategyVersionsResponseObject, error)
	// GetStrategyVersion 一個版本的 manifest
	// (GET /strategies/{strategy_id}/versions/{ref})
	GetStrategyVersion(ctx context.Context, request GetStrategyVersionRequestObject) (GetStrategyVersionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

